/**
 * Apply patch and create commit
 */
private async applyPatchAndCommit(
  context: PRContext,
  workDir: string,
  patch: { file: string; content: string; description: string },
  runId: string,
  iteration: number
): Promise<string> {
  // Generate commit message with provenance
  const commitMessage = `[gravito:${runId}] ${patch.description}\n\nIteration ${iteration}\nFile: ${patch.file}`;

  // In production, would actually write file and commit
  // For now, return simulated SHA
  const sha = crypto.createHash('sha256')
    .update(`${runId}-${iteration}-${patch.file}`)
    .digest('hex')
    .substring(0, 7);

  return sha;
}

/**
 * Generate all artifacts for a run
 */
private async generateArtifacts(
  runId: string,
  auditResult: any,
  commits: string[]
): Promise<Array<{ name: string; url: string; type: string }>> {
  const artifacts: Array<{ name: string; url: string; type: string }> = [];

  // Create decision trace
  const decisionTrace = this.artifactGen.createDecisionTrace(runId);
  decisionTrace.spans = (auditResult.issues || []).map((issue: any, i: number) => ({
    spanId: `span_${i}`,
    traceId: decisionTrace.traceId,
    operationName: 'flag_issue',
    startTime: new Date().toISOString(),
    endTime: new Date().toISOString(),
    status: 'completed' as const,
    attributes: { issueType: issue.type, severity: issue.severity },
    events: [{ name: 'issue_detected', timestamp: new Date().toISOString(), attributes: { message: issue.message } }],
  }));

  // Create run report matching AgentRunReport interface
  const runReport = {
    runId,
    surface: 'website',
    repo: 'gravito/website',
    prNumber: 1,
    triggeredBy: 'github-webhook',
    triggerType: 'webhook' as const,
    startedAt: new Date().toISOString(),
    finishedAt: new Date().toISOString(),
    status: auditResult.passed ? 'passed' as const : 'blocked' as const,
    iterations: 1,
    patchesApplied: commits.length,
    tokensUsed: 0,
    proofBlockId: `pb_${runId}`,
    previousRunHash: '',
    runHash: crypto.randomBytes(16).toString('hex'),
    gateDecision: {
      decision: auditResult.passed ? 'pass' as const : 'block' as const,
      score: auditResult.score,
      threshold: 75,
      rubricScores: emptyArray(),
      issues: (auditResult.issues || []).map((i: any) => ({
        id: `issue_${Math.random().toString(36).substr(2, 9)}`,
        type: i.type,
        severity: i.severity as 'critical' | 'high' | 'medium' | 'low',
        message: i.message,
        location: null,
        suggestion: null,
      })),
      recommendations: [],
      businessTruthCheck: {
        passed: true,
        claimsValidated: 0,
        claimsRejected: 0,
        forbiddenPatternsFound: [],
        requiredDisclosuresPresent: true,
      },
      identityCheck: {
        passed: true,
        divergenceScore: 100 - auditResult.score,
        canonicalAlignment: auditResult.score,
        forbiddenIdentitiesFound: [],
        buyerAlignmentScore: auditResult.score,
      },
    },
    patches: [],
    metadata: {},
  };

  // Generate all artifacts
  const generatedArtifacts = await this.artifactGen.generateAllArtifacts(runReport, decisionTrace);

  artifacts.push(
    { name: 'agent_run_report.json', url: generatedArtifacts.runReportJson.url || `/artifacts/${runId}/agent_run_report.json`, type: 'json' },
    { name: 'gate_report.json', url: generatedArtifacts.gateReportJson.url || `/artifacts/${runId}/gate_report.json`, type: 'json' },
