/**
 * GitHub App Integration for Real Webhook Events
 * 
 * This module handles real GitHub webhook events and executes
 * the Gravito PR Agent workflow on actual repositories.
 * 
 * Uses Claude+OpenAI+Gravito for:
 * - Claude: Generates patches and explanations
 * - OpenAI: Cross-check logging (optional)
 * - Gravito: Gate verification (never same model as generator)
 */

import crypto from 'crypto';
import { securityLog } from '../_core/logger';
import { PRCommandHandler, ParsedCommand, CommandType, PermissionConfig, RateLimitConfig } from './pr-commands';

// Gravito command type for webhook handling
export interface GravitoCommand {
  type: CommandType;
  args: string[];
  raw: string;
}
import { GitOperations } from './git-operations';
import { ArtifactGenerator } from './artifact-generator';
import { SiteGraphArtifactGenerator } from './sitegraph-artifact';
import { governedGenerate } from '../governance/governed-generate';
import { GitHubContentFetcher, ArtifactBundle, formatBundleForLLM, FetchResult } from './github-content-fetcher';
import { validateMultiModel, normalizeAuditOutput, getMultiModelValidationSummary, AuditOutput } from './validation';
import { checkIdempotency, createAuditRun, markAuditRunning, completeAuditRun, failAuditRun, formatCachedResultComment, PROMPT_VERSION, POLICY_VERSION } from './idempotency';
import { checkRateLimit, formatRateLimitComment } from './rate-limiter';
import { emptyArray, shapeCast} from '../../shared/type-bridge';
import { MODELS } from "../_core/models";

// GitHub webhook event types
export interface GitHubWebhookEvent {
  action: string;
  repository: {
    full_name: string;
    clone_url: string;
    default_branch: string;
  };
  pull_request?: {
    number: number;
    title: string;
    body: string;
    head: {
      ref: string;
      sha: string;
    };
    base: {
      ref: string;
    };
    user: {
      login: string;
    };
    html_url: string;
  };
  // For issue_comment events, the issue object contains PR info
  issue?: {
    number: number;
    title: string;
    body?: string;
    user: {
      login: string;
    };
    pull_request?: {
      url: string;
    };
  };
  comment?: {
    id: number;
    body: string;
    user: {
      login: string;
    };
  };
  sender: {
    login: string;
  };
  installation?: {
    id: number;
  };
}

export interface GitHubAppConfig {
  appId: string;
  privateKey: string;
  webhookSecret: string;
  clientId?: string;
  clientSecret?: string;
}

export interface PRContext {
  repo: string;
  prNumber: number;
  branch: string;
  baseBranch: string;
  author: string;
  title: string;
  installationId?: number;
  headSha?: string; // HEAD SHA for idempotency
  triggeredBy?: string; // User who triggered the command
}

export interface GitHubAPIResponse {
  success: boolean;
  data?: any;
  error?: string;
}

/**
 * GitHub App Integration Class
 * 
 * Handles webhook verification, event processing, and GitHub API calls
 */
export class GitHubApp {
  private config: GitHubAppConfig & { adminAllowlist?: string[] };
  private commandHandler: PRCommandHandler;
  private gitOps: GitOperations;
  private artifactGen: ArtifactGenerator;
  private siteGraphGen: SiteGraphArtifactGenerator;
  private contentFetcher: GitHubContentFetcher;
  private accessTokens: Map<number, { token: string; expiresAt: Date }> = new Map();

  constructor(config: GitHubAppConfig) {
    // Convert escaped newlines in private key to actual newlines
    if (config.privateKey) {
      config.privateKey = config.privateKey.replace(/\\n/g, '\n');
    }
    this.config = config;
    this.commandHandler = new PRCommandHandler(
      {
        repoAllowlist: [], // Will be populated from config
        adminAllowlist: [],
        forkAllowlist: [],
        blockedPages: ['auth', 'payments', 'security', 'legal'],
      },
      {
        maxRunsPerPRPerHour: 3,
        maxRunsPerRepoPerDay: 50,
        maxTokensPerDay: 1000000,
      }
    );
    this.gitOps = new GitOperations();
    this.artifactGen = new ArtifactGenerator();
    this.siteGraphGen = new SiteGraphArtifactGenerator();
    this.contentFetcher = new GitHubContentFetcher((installationId) => this.getInstallationToken(installationId));
  }

  /**
   * Verify webhook signature using HMAC-SHA256
   */
  verifyWebhookSignature(payload: string, signature: string): boolean {
    if (!signature) return false;

    const expectedSignature = 'sha256=' + crypto
      .createHmac('sha256', this.config.webhookSecret)
      .update(payload)
      .digest('hex');

    try {
      return crypto.timingSafeEqual(
        Buffer.from(signature),
        Buffer.from(expectedSignature)
      );
    } catch {
      return false;
    }
  }

  /**
   * Get installation access token for GitHub API calls
   */
  async getInstallationToken(installationId: number): Promise<string> {
    // Check cache
    const cached = this.accessTokens.get(installationId);
    if (cached && cached.expiresAt > new Date()) {
      return cached.token;
    }

    // Generate JWT for app authentication
    const now = Math.floor(Date.now() / 1000);
    const jwt = this.generateJWT(now);

    try {
      // Exchange JWT for installation token via GitHub API
      const response = await fetch(
        `https://api.github.com/app/installations/${installationId}/access_tokens`,
        {
          method: 'POST',
          headers: {
            'Authorization': `Bearer ${jwt}`,
            'Accept': 'application/vnd.github+json',
            'X-GitHub-Api-Version': '2022-11-28',
          },
        }
      );

      if (!response.ok) {
        const errorText = await response.text();
        securityLog.error({ status: response.status, errorText }, '[GitHubApp] Failed to get installation token');
        throw new Error(`Failed to get installation token: ${response.status}`);
      }

      const data = await response.json() as { token: string; expires_at: string };

      this.accessTokens.set(installationId, {
        token: data.token,
        expiresAt: new Date(data.expires_at),
      });

      securityLog.info({ installationId }, '[GitHubApp] Got installation token');
      return data.token;
    } catch (error) {
      securityLog.error({ err: error instanceof Error ? error : new Error(String(error)), installationId }, '[GitHubApp] Error getting installation token');
      throw error instanceof Error ? error : new Error(String(error));
    }
  }

  /**
   * Generate JWT for GitHub App authentication
   */
  private generateJWT(now: number): string {
    // JWT header and payload
    const header = { alg: 'RS256', typ: 'JWT' };
    const payload = {
      iat: now - 60,
      exp: now + 600,
      iss: this.config.appId,
    };

    const encodedHeader = Buffer.from(JSON.stringify(header)).toString('base64url');
    const encodedPayload = Buffer.from(JSON.stringify(payload)).toString('base64url');

    if (!this.config.privateKey?.trim()) {
      throw new Error('[GitHubApp] GITHUB_APP_PRIVATE_KEY (or config.privateKey) is required to sign installation JWTs');
    }
    try {
      const sign = crypto.createSign('RSA-SHA256');
      sign.update(`${encodedHeader}.${encodedPayload}`);
      const signature = sign.sign(this.config.privateKey, 'base64url');
      return `${encodedHeader}.${encodedPayload}.${signature}`;
    } catch (error) {
      securityLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[GitHubApp] Error signing JWT');
      throw error instanceof Error ? error : new Error(String(error));
    }
  }

  /**
   * Process incoming webhook event
   */
  async processWebhookEvent(event: GitHubWebhookEvent): Promise<{
    processed: boolean;
    action?: string;
    result?: any;
    error?: string;
  }> {
    // Handle PR comment events (command triggers)
    // For issue_comment events on PRs, the PR info is in the `issue` object with a `pull_request` field
    const isCommentOnPR = event.action === 'created' && event.comment && 
      (event.pull_request || event.issue?.pull_request);

    if (isCommentOnPR) {
      return this.handlePRComment(event);
    }

    // Handle PR opened/synchronized events
    if (event.pull_request && ['opened', 'synchronize'].includes(event.action)) {
      return this.handlePREvent(event);
    }

    return { processed: false, action: 'ignored' };
  }

  /**
   * Handle PR comment containing /gravito command
   * 
   * Note: For issue_comment events on PRs, GitHub sends the PR info in the `issue` object,
   * not the `pull_request` object. The full PR details need to be fetched from the API.
   */
  private async handlePRComment(event: GitHubWebhookEvent): Promise<{
    processed: boolean;
    action?: string;
    result?: any;
    error?: string;
  }> {
    const comment = event.comment!;
    const repo = event.repository.full_name;

    // Check if comment contains /gravito command
    if (!comment.body.includes('/gravito')) {
      return { processed: false, action: 'no_command' };
    }

    // For issue_comment events, PR info is in the issue object
    // The pull_request field exists only if the issue is a PR
    const pr = event.pull_request;
    const issue = event.issue;

    // Determine PR number from either source
    const prNumber = pr?.number ?? issue?.number;
    if (!prNumber) {
      return { processed: false, action: 'no_pr_context', error: 'Could not determine PR number' };
    }

    // Check if this is actually a PR (not just an issue)
    if (!pr && !issue?.pull_request) {
      return { processed: false, action: 'not_a_pr', error: 'Comment is on an issue, not a PR' };
    }

    // Parse command
    const command = this.commandHandler.parseCommand(
      comment.body,
      comment.id.toString(),
      comment.user.login,
      repo,
      prNumber
    );
    if (!command) {
      return { processed: false, action: 'invalid_command' };
    }

    // Build PR context with available data
    // For issue_comment events, we may not have full PR details
    const context: PRContext = {
      repo,
      prNumber,
      // Use available data or defaults
      branch: pr?.head?.ref ?? issue?.title?.split(' ')[0] ?? 'unknown',
      baseBranch: pr?.base?.ref ?? event.repository.default_branch ?? 'main',
      author: pr?.user?.login ?? issue?.user?.login ?? event.sender.login,
      title: pr?.title ?? issue?.title ?? `PR #${prNumber}`,
      installationId: event.installation?.id,
      headSha: pr?.head?.sha,
      triggeredBy: comment.user.login,
    };

    // Execute command
    try {
      const result = await this.executeCommand(command, context, comment.user.login);
      return {
        processed: true,
        action: command.type,
        result,
      };
    } catch (error) {
      securityLog.error({ err: error instanceof Error ? error : new Error(String(error)), commandType: command.type }, '[GitHubApp] Error executing command');
      return {
        processed: false,
        action: command.type,
        error: error instanceof Error ? error.message : 'Unknown error',
      };
    }
  }

  /**
   * Handle PR opened/synchronized event
   */
  private async handlePREvent(event: GitHubWebhookEvent): Promise<{
    processed: boolean;
    action?: string;
    result?: any;
    error?: string;
  }> {
    const pr = event.pull_request!;
    const repo = event.repository.full_name;

    // Build context
    const context: PRContext = {
      repo,
      prNumber: pr.number,
      branch: pr.head.ref,
      baseBranch: pr.base.ref,
      author: pr.user.login,
      title: pr.title,
      installationId: event.installation?.id,
      headSha: pr.head.sha,
      triggeredBy: pr.user.login,
    };

    // Auto-audit on PR open (if enabled)
    // For now, just acknowledge the event
    return {
      processed: true,
      action: 'pr_' + event.action,
      result: {
        message: `PR #${pr.number} ${event.action}`,
        context,
      },
    };
  }

  /**
   * Execute a Gravito command
   */
  async executeCommand(
    command: GravitoCommand,
    context: PRContext,
    executor: string
  ): Promise<any> {
    // Generate run ID
    const runId = this.commandHandler.generateRunId('website');

    // Post acknowledgment comment
    await this.postComment(context, `🤖 Starting \`${runId}\`\n\nCommand: \`/gravito ${command.type}\`\nExecutor: @${executor}`);

    switch (command.type) {
      case 'run':
        return this.executeRun(context, runId);
      case 'fix':
        return this.executeFix(context, runId);
      case 'explain':
        return this.executeExplain(context, runId, command.args);
      case 'status':
        return this.executeStatus(context, runId);
      case 'rollback':
        return this.executeRollback(context, runId, command.args);
      case 'autopilot':
        return this.executeAutopilot(context, runId, command.args, executor);
      default:
        throw new Error(`Unknown command: ${command.type}`);
    }
  }

  /**
   * Execute /gravito run - full audit without changes
   */
  private async executeRun(context: PRContext, runId: string): Promise<any> {
    const startTime = Date.now();

    try {
      securityLog.info({ runId }, '[GitHubApp] executeRun started');

      // Get the PR SHA for idempotency
      const prSha = context.headSha || 'unknown';

      // Extract org from repo (e.g., "owner/repo" -> "owner")
      const org = context.repo.split('/')[0];

      // Check rate limits before proceeding
      const rateLimitStatus = await checkRateLimit({ repo: context.repo, org });
      if (!rateLimitStatus.allowed) {
        securityLog.info({ repo: context.repo, reason: rateLimitStatus.reason }, '[GitHubApp] Rate limit exceeded');

        // Post rate limit comment
        await this.postComment(context, formatRateLimitComment(rateLimitStatus, runId));

        return {
          runId,
          status: 'rate_limited',
          reason: rateLimitStatus.reason,
          retryAfter: rateLimitStatus.retryAfter,
        };
      }

      // Check idempotency - return cached result if same PR state already audited
      const idempotencyCheck = await checkIdempotency({
        repo: context.repo,
        prNumber: context.prNumber,
        prSha,
      });

      if (idempotencyCheck.cached && idempotencyCheck.existingRun) {
        const cachedRun = idempotencyCheck.existingRun;
        securityLog.info({ cachedRunId: cachedRun.runId }, '[GitHubApp] Returning cached result');

        // Post cached result comment
        await this.postComment(context, formatCachedResultComment(cachedRun));

        return {
          runId: cachedRun.runId,
          status: cachedRun.passed ? 'pass' : 'fail',
          score: cachedRun.score,
          cached: true,
          originalRunId: cachedRun.runId,
        };
      }

      // Create new audit run record
      let auditRun;
      try {
        auditRun = await createAuditRun({
          repo: context.repo,
          prNumber: context.prNumber,
          prSha,
          runId,
          triggeredBy: context.triggeredBy || 'unknown',
          triggerType: 'comment',
          installationId: context.installationId,
          primaryModel: MODELS.generation,
          primaryProvider: 'anthropic',
        });
        await markAuditRunning(runId);
      } catch (dbError) {
        securityLog.warn({ err: dbError instanceof Error ? dbError : new Error(String(dbError)) }, '[GitHubApp] Failed to create audit run record');
        // Continue without DB tracking
      }

      // Clone repo and checkout PR branch
      const workDir = `/tmp/gravito/${runId}`;

      // Run audit using Claude for analysis
      securityLog.info({ runId }, '[GitHubApp] Running audit');
      const auditResult = await this.runAudit(context, workDir, runId);
      securityLog.info({ runId, score: auditResult.score, passed: auditResult.passed }, '[GitHubApp] Audit completed');

      // Generate artifacts
      securityLog.info({ runId }, '[GitHubApp] Generating artifacts');
      const artifacts = await this.generateArtifacts(runId, auditResult, []);
      securityLog.info({ runId, count: artifacts?.length || 0 }, '[GitHubApp] Artifacts generated');

      // Post results
      securityLog.info({ runId }, '[GitHubApp] Posting comment');
      await this.postComment(context, this.formatAuditComment(runId, auditResult, artifacts));
      securityLog.info({ runId }, '[GitHubApp] Comment posted successfully');

      // Complete the audit run record
      const durationMs = Date.now() - startTime;
      try {
        await completeAuditRun(runId, {
          score: auditResult.score,
          passed: auditResult.passed,
          issues: auditResult.issues || [],
          filesAnalyzed: auditResult.artifactBundle?.files.map(f => f.path) || [],
          durationMs,
          markdownSummary: this.formatAuditComment(runId, auditResult, artifacts),
          fullResult: auditResult,
        });
        securityLog.info({ runId }, '[GitHubApp] Audit run record completed');
      } catch (dbError) {
        securityLog.warn({ err: dbError instanceof Error ? dbError : new Error(String(dbError)), runId }, '[GitHubApp] Failed to complete audit run record');
      }

      return {
        runId,
        status: auditResult.passed ? 'pass' : 'fail',
        score: auditResult.score,
        artifacts,
        durationMs,
      };
    } catch (error) {
      securityLog.error({ err: error instanceof Error ? error : new Error(String(error)), runId }, '[GitHubApp] executeRun error');
      // Stack trace included in the err object above

      // Mark the audit run as failed
      try {
        await failAuditRun(
          runId,
          error instanceof Error ? error.name : 'UNKNOWN_ERROR',
          error instanceof Error ? error.message : String(error)
        );
      } catch (dbError) {
        securityLog.warn({ err: dbError instanceof Error ? dbError : new Error(String(dbError)), runId }, '[GitHubApp] Failed to mark audit run as failed');
      }

      throw error;
    }
  }

  /**
   * Execute /gravito fix - audit, patch, and iterate until PASS
   */
  private async executeFix(context: PRContext, runId: string): Promise<any> {
    const workDir = `/tmp/gravito/${runId}`;
    const maxIterations = 3;
    const commits: string[] = [];
    let iteration = 0;
    let currentScore = 0;
    let passed = false;

    while (iteration < maxIterations && !passed) {
      iteration++;

      // Run audit
      const auditResult = await this.runAudit(context, workDir, runId);
      currentScore = auditResult.score;
      passed = auditResult.passed;

      if (passed) {
        break;
      }

      // Generate patches using Claude
      const patches = await this.generatePatches(auditResult.issues || [], runId);

      // Apply patches and commit
      for (const patch of patches) {
        const commitSha = await this.applyPatchAndCommit(
          context,
          workDir,
          patch,
          runId,
          iteration
        );
        commits.push(commitSha);
      }

      // Post iteration update
      await this.postComment(context, 
        `📊 **Iteration ${iteration}/${maxIterations}**\n\n` +
        `Score: ${currentScore}/100\n` +
        `Status: ${passed ? '✅ PASS' : '🔄 Continuing...'}\n` +
        `Commits: ${commits.length}`
      );
    }

    // Generate final artifacts
    const finalAudit = await this.runAudit(context, workDir, runId);
    const artifacts = await this.generateArtifacts(runId, finalAudit, commits);

    // Post final results
    const status = finalAudit.passed ? '✅ PASS' : '⚠️ MAX_ITERATIONS';
    await this.postComment(context,
      `## 🤖 Gravito Fix Complete\n\n` +
      `**Run ID:** \`${runId}\`\n` +
      `**Status:** ${status}\n` +
      `**Final Score:** ${finalAudit.score}/100\n` +
      `**Iterations:** ${iteration}/${maxIterations}\n` +
      `**Commits:** ${commits.length}\n\n` +
      `### Artifacts\n` +
      (artifacts || []).map(a => `- [${a.name}](${a.url})`).join('\n')
    );

    return {
      runId,
      status: finalAudit.passed ? 'pass' : 'max_iterations',
      score: finalAudit.score,
      iterations: iteration,
      commits,
      artifacts,
    };
  }

